import fs from 'fs';
import path from 'path';

const TGCLOUD_DIR = '.tgcloud';

function isProjectDir(dir) {
  try {
    return fs.statSync(path.join(dir, TGCLOUD_DIR)).isDirectory();
  } catch {
    return false;
  }
}

/** Nearest ancestor of `start` (inclusive) containing `.tgcloud/`; absolute path or null. */
export function findProjectRoot(start = process.cwd()) {
  let dir = path.resolve(start);
  while (true) {
    if (isProjectDir(dir)) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) return null; // reached the filesystem root
    dir = parent;
  }
}

/**
 * chdir into the project root so CWD-relative file access resolves against it.
 * No-op when no project is found. Returns the root, or null.
 */
export function enterProjectRoot() {
  const root = findProjectRoot();
  if (root && root !== process.cwd()) process.chdir(root);
  return root;
}
